parameters.jsCode:
function hex32() {
  let out = '';
  for (let i = 0; i < 32; i += 1) out += Math.floor(Math.random() * 16).toString(16);
  return out;
}
function hex16() { return hex32().slice(0, 16); }
function toUnixNano(iso) {
  const ms = Date.parse(iso);
  if (Number.isNaN(ms)) throw new Error('Invalid ISO timestamp: ' + iso);
  return String(BigInt(ms) * 1000000n);
}
function strAttr(key, value) { return { key, value: { stringValue: String(value) } }; }
function arrAttr(key, values) {
  return { key, value: { arrayValue: { values: values.map((v) => ({ stringValue: String(v) })) } } };
}
function extractText(out) {
  if (typeof out === 'string') return out;
  if (out && typeof out.text === 'string') return out.text;
  if (out && typeof out.output === 'string') return out.output;
  return JSON.stringify(out);
}

const cfg = $('Input Text').first().json;
const row = $('Get row(s) in sheet').first().json;
const extractorOut = extractText($('Requirement Extractor1').first().json);
const prdOut = extractText($('PRD Generator').first().json);
const storyOut = extractText($('PRD Breakdown Agent').first().json);
const gapOut = extractText($('Gap Analyzer Agent').first().json);
const chatInput = typeof row.chatInput === 'string' ? row.chatInput : '';
const testId = cfg.testId || row.testId || 'T1';
const startTime = cfg.startTime || new Date().toISOString();
const endTime = new Date().toISOString();
const startNano = toUnixNano(startTime);
const endNano = toUnixNano(endTime);
const traceId = hex32();
const rootSpanId = hex16();
const tags = ['prd-genie', 'slice1', testId];
const shared = [
  strAttr('langfuse.trace.name', 'prd-genie-slice1'),
  arrAttr('langfuse.trace.tags', tags),
  strAttr('langfuse.release', 'R1'),
  strAttr('langfuse.environment', 'prd-genie-capstone'),
  strAttr('langfuse.trace.metadata.testId', testId),
  strAttr('langfuse.trace.metadata.release', 'R1'),
  strAttr('langfuse.trace.metadata.platform', 'n8n-ik-cloud'),
];
const agents = [
  { name: 'Requirement Extractor', model: 'gpt-4o', input: chatInput, output: extractorOut },
  { name: 'PRD Generator', model: 'gpt-4o', input: extractorOut, output: prdOut },
  { name: 'Story Breakdown', model: 'gpt-4o-mini', input: prdOut, output: storyOut },
  { name: 'Gap Analyzer', model: 'gpt-4o-mini', input: extractorOut, output: gapOut },
];
const generations = agents.map(function (agent) {
  return {
    traceId: traceId,
    spanId: hex16(),
    parentSpanId: rootSpanId,
    name: agent.name,
    kind: 1,
    startTimeUnixNano: startNano,
    endTimeUnixNano: endNano,
    attributes: shared.concat([
      strAttr('langfuse.observation.type', 'generation'),
      strAttr('langfuse.observation.input', agent.input),
      strAttr('langfuse.observation.output', agent.output),
      strAttr('langfuse.observation.model.name', agent.model),
      strAttr('gen_ai.request.model', agent.model),
      strAttr('langfuse.observation.metadata.testId', testId),
      strAttr('langfuse.observation.metadata.agent', agent.name),
    ]),
  };
});
const otlp = {
  resourceSpans: [{
    resource: { attributes: [strAttr('service.name', 'prd-genie'), strAttr('service.version', 'R1')] },
    scopeSpans: [{
      scope: { name: 'prd-genie-n8n', version: 'v4' },
      spans: [{
        traceId: traceId,
        spanId: rootSpanId,
        name: 'prd-genie-slice1',
        kind: 1,
        startTimeUnixNano: startNano,
        endTimeUnixNano: endNano,
        attributes: shared.concat([
          strAttr('langfuse.observation.type', 'span'),
          strAttr('langfuse.observation.input', chatInput),
          strAttr('langfuse.observation.output', storyOut),
        ]),
      }].concat(generations),
    }],
  }],
};
return [{ json: { otlp: otlp, traceId: traceId, testId: testId, extractorOutput: extractorOut, prdOutput: prdOut, storyOutput: storyOut, gapOutput: gapOut } }];
